import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { createInterface } from 'node:readline';

// Only files generated by installKit may enter the setup commit.
export const SETUP_FILES = [
  'agentstalk/channel.mjs', 'agentstalk/config.json', 'agentstalk/github-repo.mjs',
  'agentstalk/hook.mjs', 'agentstalk/join.mjs', 'agentstalk/mcp-proxy.mjs',
  'agentstalk/package.json', 'agentstalk/pre-commit.mjs',
  'AGENTS.md', '.claude/settings.json', '.codex/config.toml', '.mcp.json',
];

function git(root, ...args) {
  return execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
}

export function prepareInit(root) {
  const branch = git(root, 'branch', '--show-current');
  if (!branch) throw new Error('Switch to a branch before running init.');
  for (const state of ['MERGE_HEAD', 'CHERRY_PICK_HEAD', 'REVERT_HEAD', 'rebase-merge', 'rebase-apply']) {
    const file = git(root, 'rev-parse', '--git-path', state);
    if (fs.existsSync(path.resolve(root, file))) throw new Error('Finish the current merge, rebase, or cherry-pick before running init.');
  }
  if (git(root, 'status', '--porcelain', '--untracked-files=all', '--', ...SETUP_FILES)) {
    throw new Error('Save or stash your existing changes to agentsTalk setup files before running init.');
  }
  try {
    for (const identity of ['GIT_AUTHOR_IDENT', 'GIT_COMMITTER_IDENT']) git(root, 'var', identity);
  } catch { throw new Error('Configure your Git name and email before running init.'); }
  return branch;
}

export async function confirmInit(repo, branch, { yes = false, input = process.stdin, output = process.stdout } = {}) {
  output.write(`\nWarning: this will install agentsTalk in ${repo}, connect your coding agents,\ncommit its setup files, and push the current branch (${branch}) to origin.\nEarlier unpushed commits on this branch will also be uploaded. Personal keys stay local.\n`);
  if (yes) { output.write('Continuing as requested with --yes.\n'); return true; }
  const lines = createInterface({ input, output, terminal: Boolean(input.isTTY && output.isTTY) });
  try {
    output.write('Continue? [y/N] ');
    for await (const answer of lines) return /^(y|yes)$/i.test(answer.trim());
    return false;
  } finally { lines.close(); }
}

export function commitAndPushSetup(root, branch) {
  if (git(root, 'branch', '--show-current') !== branch) throw new Error('The branch changed during setup. Run init again on the intended branch.');
  git(root, 'add', '--', ...SETUP_FILES);
  if (git(root, 'diff', '--cached', '--name-only', '--', ...SETUP_FILES)) {
    try {
      // --only preserves unrelated staged work and excludes it from this commit.
      git(root, 'commit', '--only', '-m', 'Set up agentsTalk for the team', '--', ...SETUP_FILES);
    } catch {
      throw new Error('Setup files are ready, but Git refused the setup commit. Resolve your commit hook or signing error, then commit and push the generated setup files.');
    }
    console.log('Committed agentsTalk setup files.');
  } else console.log('Setup files are already committed.');
  try {
    git(root, 'push', '--set-upstream', 'origin', 'HEAD');
  } catch {
    throw new Error('Setup is committed locally, but the push failed. Check GitHub access or remote changes, then retry: git push --set-upstream origin HEAD');
  }
  console.log(`Pushed ${branch} to origin. Teammates can clone this branch and run npx agentstalk.`);
}
